use bigdecimal::BigDecimal;
use chrono::{DateTime, Utc};
use serde_json::Value;
use sqlx::PgConnection;

use thiserror::Error;

/*
 * Snapshot of a job immediately after this worker successfully claims it.
 *
 * organization_id is BigDecimal because the application organization ID is
 * also an on-chain u64. PostgreSQL BIGINT is signed and cannot represent the
 * complete u64 range, so the database stores it as NUMERIC(20, 0), which SQLx
 * maps to BigDecimal.
 *
 * job_id and submission_id are PostgreSQL BIGINT identity values generated by
 * our application database. They only need the signed i64 range.
 *
 * organization_id, submission_id and idempotency_key are optional because
 * jobs is a generic queue:
 *
 * - an organization reconciliation job has organization_id;
 * - a transaction reconciliation job also has submission_id;
 * - a global maintenance job may have neither;
 * - idempotency_key is optional at the schema level, although important
 *   application jobs should normally provide one.
 *
 * The processor for each job type must validate that the fields required by
 * that specific job type are present.
 */
#[derive(Debug)]
pub struct ClaimedJob {
    pub job_id: i64,

    pub organization_id: Option<BigDecimal>,
    pub submission_id: Option<i64>,

    pub job_type: String,
    pub payload: Value,
    pub idempotency_key: Option<String>,

    /*
     * attempts counts how many times processing has started, not merely how
     * many failures have occurred. It is incremented during the claim.
     *
     * The attempt number also acts as a fencing token. If attempt 1 becomes
     * stale and the job is later claimed as attempt 2, attempt 1 can no longer
     * update the job.
     */
    pub attempts: i32,
    pub max_attempts: i32,

    /*
     * These fields describe the current temporary ownership of a running job.
     *
     * locked_by identifies the worker.
     * locked_at records when it acquired the job.
     * lease_expires_at limits how long that ownership remains valid.
     *
     * They are populated only while the job is running and cleared when the
     * job is requeued or reaches a terminal state.
     */
    pub locked_at: DateTime<Utc>,
    pub locked_by: String,
    pub lease_expires_at: DateTime<Utc>,
}

/*
 * Result of recording a processing failure.
 *
 * Requeued means another attempt remains and the job will become eligible
 * again after run_at.
 *
 * Dead means the retry budget has been exhausted and the queue will not claim
 * the job again automatically.
 */
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum JobFailureDisposition {
    Requeued,
    Dead,
}

/*
 * Errors produced by queue ownership and state-transition operations.
 *
 * Database wraps an underlying SQLx/PostgreSQL error.
 *
 * LeaseLost means the conditional UPDATE matched no row. The job may have
 * expired, been recovered, been claimed by another worker, or already reached
 * another state.
 *
 * UnexpectedStatus protects us from silently accepting a database state that
 * this function was not designed to return.
 */
#[derive(Debug, Error)]
pub enum JobQueueError {
    #[error(transparent)]
    Database(#[from] sqlx::Error),

    #[error("job {job_id} lease was lost for worker {worker_id} attempt {attempt}")]
    LeaseLost {
        job_id: i64,
        worker_id: String,
        attempt: i32,
    },

    #[error("job operation produced unexpected status {0}")]
    UnexpectedStatus(String),

    #[error(
        "job {job_id} cannot be deferred because attempt {attempt} reached max attempts {max_attempts}"
    )]
    DeferralBudgetExhausted {
        job_id: i64,
        attempt: i32,
        max_attempts: i32,
    },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LeaseRecoverySummary {
    pub requeued: u64,
    pub dead: u64,
}

/*
 * Atomically finds one due job and leases it to this worker.
 *
 * The caller owns the surrounding database transaction. The caller should
 * commit immediately after a successful claim so that:
 *
 * - the running state becomes visible to other workers;
 * - the row lock is released quickly;
 * - no database lock is held while performing Solana RPC calls.
 *
 * None means there is currently no unlocked, due job of this type with retry
 * attempts remaining.
 */
pub async fn claim_next_job(
    connection: &mut PgConnection,
    worker_id: &str,
    job_type: &str,
    lease_seconds: i64,
) -> Result<Option<ClaimedJob>, sqlx::Error> {
    /*
     * Select one eligible job:
     *
     * - queued: it currently has no owner;
     * - matching job type: this worker knows how to process it;
     * - run_at <= now(): its retry delay has elapsed;
     * - attempts < max_attempts: it still has retry budget.
     *
     * Lower priority numbers run first. run_at orders jobs by when they
     * became eligible, and job_id provides deterministic tie-breaking.
     *
     * The CTE identifies the next eligible row.
     *
     * FOR UPDATE takes a row lock so another worker cannot claim the same job.
     * SKIP LOCKED tells concurrent workers to skip an already locked row and
     * continue looking instead of waiting.
     *
     * Selection and UPDATE are part of one SQL statement, so there is no
     * unlocked gap between finding the job and changing it to running.
     *
     * Claiming changes the job to running, consumes one attempt, and creates
     * a temporary lease owned by worker_id.
     *
     * Incrementing attempts during claim ensures that a worker crash still
     * consumes an attempt; otherwise a crashing job could retry forever.
     */
    sqlx::query_as!(
        ClaimedJob,
        r#"
        WITH candidate as (
            SELECT job_id
            FROM jobs
            WHERE 
                status = 'queued'
                AND job_type = $1
                AND run_at <= now()
                AND attempts < max_attempts
            ORDER BY 
                priority ASC,
                run_at ASC,
                job_id ASC
            FOR UPDATE SKIP LOCKED
            LIMIT 1
        )
        UPDATE jobs as job
        SET 
            status = 'running',
            attempts = job.attempts + 1,
            locked_at = now(),
            locked_by = $2,
            lease_expires_at = now() + ($3::BIGINT * INTERVAL '1 second')
        FROM candidate
        WHERE job.job_id = candidate.job_id
        RETURNING
            job.job_id,
            job.organization_id,
            job.submission_id,
            job.job_type,
            job.payload,
            job.idempotency_key,
            job.attempts,
            job.max_attempts,
            job.locked_at AS "locked_at!",
            job.locked_by AS "locked_by!",
            job.lease_expires_at AS "lease_expires_at!"
        "#,
        job_type,
        worker_id,
        lease_seconds
    )
    .fetch_optional(connection)
    .await
}

/*
 * Marks a job successful only if this caller still owns the current lease.
 *
 * The WHERE clause combines lease validation and state transition into one
 * atomic UPDATE. It checks:
 *
 * - the expected job;
 * - that the job is still running;
 * - the same worker still owns it;
 * - this is still the same attempt;
 * - the lease has not expired.
 *
 * On success, the job enters a terminal state and no worker owns it anymore,
 * so all temporary lease fields are cleared.
 *
 * If no row matches, the caller has lost ownership and must NOT report the job
 * as successful.
 */
pub async fn mark_job_succeeded(
    connection: &mut PgConnection,
    claimed_job: &ClaimedJob,
) -> Result<(), JobQueueError> {
    let completed_job_id = sqlx::query_scalar!(
        r#"
            UPDATE jobs
            SET
                status = 'succeeded',
                completed_at = now(),
                last_error = NULL,
                lease_expires_at = NULL,
                locked_at = NULL,
                locked_by = NULL

            WHERE status = 'running'
                AND job_id = $1
                AND attempts = $2
                AND locked_by = $3
                AND lease_expires_at > now()


            RETURNING job_id
        "#,
        claimed_job.job_id,
        claimed_job.attempts,
        &claimed_job.locked_by,
    )
    .fetch_optional(connection)
    .await?;

    if completed_job_id.is_none() {
        return Err(JobQueueError::LeaseLost {
            job_id: claimed_job.job_id,
            worker_id: claimed_job.locked_by.clone(),
            attempt: claimed_job.attempts,
        });
    }

    Ok(())
}

/*
 * Records a processing failure only if this worker still owns the current
 * unexpired lease.
 *
 * If retry attempts remain:
 *
 * - status becomes queued;
 * - run_at applies the requested retry delay;
 * - completed_at remains NULL;
 * - lease ownership is released.
 *
 * If the current attempt exhausted max_attempts:
 *
 * - status becomes dead;
 * - completed_at records the terminal time;
 * - the job will not be claimed automatically again.
 *
 * In both cases, last_error records why processing failed, while the temporary
 * lease fields are cleared because the current worker no longer owns the job.
 *
 * The job ID, worker ID and attempt number form the ownership check. This
 * prevents a stale worker from updating a newer attempt.
 */
pub async fn record_job_failure(
    connection: &mut PgConnection,
    claimed_job: &ClaimedJob,
    retry_delay_seconds: i64,
    error_message: &str,
) -> Result<JobFailureDisposition, JobQueueError> {
    /*
     * Check the is Job claimed by the correct worker,
     * decide if requeued or dead based on max attempts.
     *
     * If a stale worker tries to update the job, the WHERE clause prevents it and sql returns None.
     * In this case, return LeaseLost Error.
     *
     * Else the job is either queued, or dead, in that case return the correct status.
     */

    let resulting_status = sqlx::query_scalar!(
        r#"
        UPDATE jobs

        SET
            status = CASE 
                WHEN attempts >= max_attempts THEN 'dead'
                ELSE 'queued'
            END,

            run_at = CASE
                WHEN attempts >= max_attempts THEN run_at
                ELSE now() + ($4::BIGINT * INTERVAL '1 second')
            END,

            completed_at = CASE
                WHEN attempts >= max_attempts THEN now()
                ELSE NULL
            END,

            last_error = $5,
            locked_at = NULL,
            locked_by = NULL,
            lease_expires_at = NULL

        WHERE status = 'running'
            AND job_id = $1
            AND attempts = $2
            AND locked_by = $3
            AND lease_expires_at > now()

        RETURNING status
        "#,
        claimed_job.job_id,
        claimed_job.attempts,
        &claimed_job.locked_by,
        retry_delay_seconds,
        error_message
    )
    .fetch_optional(connection)
    .await?;

    /*
     * fetch_optional returns:
     *
     * Some("queued") when another retry was scheduled;
     * Some("dead") when the retry budget was exhausted;
     * None when the conditional UPDATE matched no currently owned lease.
     */
    let resulting_status = match resulting_status {
        Some(status) => status,

        None => {
            return Err(JobQueueError::LeaseLost {
                job_id: claimed_job.job_id,
                worker_id: claimed_job.locked_by.clone(),
                attempt: claimed_job.attempts,
            });
        }
    };

    /*
     * Convert the persisted database state into a typed Rust result so callers
     * do not need to interpret raw status strings.
     */
    match resulting_status.as_str() {
        "queued" => Ok(JobFailureDisposition::Requeued),
        "dead" => Ok(JobFailureDisposition::Dead),
        other => Err(JobQueueError::UnexpectedStatus(other.to_owned())),
    }
}

pub async fn recover_expired_job_leases(
    connection: &mut PgConnection,
    batch_size: i64,
    retry_delay_seconds: i64,
) -> Result<LeaseRecoverySummary, JobQueueError> {
    /*
     * A job can remain in `running` if its worker crashes, loses network
     * access or is terminated before recording success or failure.
     *
     * Once lease_expires_at is in the past, that worker no longer owns
     * the job. This function releases the expired ownership and decides
     * whether the job may be attempted again.
     */

    let results = sqlx::query_scalar!(
        r#"
        WITH expired_jobs as (
            SELECT job_id
            FROM jobs
            WHERE
                status = 'running'
                AND lease_expires_at <= now()
            ORDER BY
                lease_expires_at ASC,
                job_id ASC
            FOR UPDATE SKIP LOCKED
            LIMIT $1
        )
        UPDATE jobs as job
        SET
            status = CASE
                WHEN job.attempts >= job.max_attempts THEN 'dead'
                ELSE 'queued'
            END,

            run_at = CASE
                WHEN job.attempts >= job.max_attempts THEN job.run_at
                ELSE now() + ($2::BIGINT * INTERVAL '1 second')
            END,

            completed_at = CASE
                WHEN job.attempts >= job.max_attempts THEN now()
                ELSE NULL
            END,

            last_error = CASE
                WHEN job.attempts >= job.max_attempts THEN 'worker lease expired after final attempt'
                ELSE 'worker lease expired before completion'
            END,

            locked_at = NULL,
            locked_by = NULL,
            lease_expires_at = NULL

        FROM expired_jobs
        WHERE job.job_id = expired_jobs.job_id
        RETURNING job.status
        "#,
        batch_size,
        retry_delay_seconds,
    )
    .fetch_all(connection)
    .await?;

    /*
     * RETURNING gives us one final status for every recovered job.
     *
     * Counting here lets the worker emit useful metrics such as:
     *
     *     recovered jobs: 8
     *     requeued: 7
     *     dead: 1
     */
    let mut summary = LeaseRecoverySummary {
        requeued: 0,
        dead: 0,
    };

    for status in results {
        match status.as_str() {
            "queued" => {
                summary.requeued += 1;
            }

            "dead" => {
                summary.dead += 1;
            }

            other => {
                return Err(JobQueueError::UnexpectedStatus(other.to_owned()));
            }
        }
    }

    Ok(summary)
}

pub async fn defer_job(
    connection: &mut PgConnection,
    claimed_job: &ClaimedJob,
    defer_seconds: i64,
) -> Result<(), JobQueueError> {
    if claimed_job.attempts >= claimed_job.max_attempts {
        return Err(JobQueueError::DeferralBudgetExhausted {
            job_id: claimed_job.job_id,
            attempt: claimed_job.attempts,
            max_attempts: claimed_job.max_attempts,
        });
    }

    /*
     * The worker completed this polling attempt successfully,
     * but the external operation has not yet reached a terminal state.
     *
     * If polling shows processed or confirmed, the job has to be requeued
     * and the logical lock relased without changing the attempts, last error etc.
     * This job can be claimed by another worker and the processing can be done again.
     */

    let deferred_job_id = sqlx::query_scalar!(
        r#"
        UPDATE jobs

        SET status = 'queued',
            run_at = now() + ($4::BIGINT * INTERVAL '1 second'),
            locked_by = NULL,
            lease_expires_at = NULL,
            locked_at = NULL,
            completed_at = NULL

        WHERE status = 'running'
            AND job_id = $1
            AND locked_by = $2
            AND lease_expires_at > now()
            AND attempts = $3
            AND attempts < max_attempts

        RETURNING job_id
        "#,
        claimed_job.job_id,
        &claimed_job.locked_by,
        claimed_job.attempts,
        defer_seconds
    )
    .fetch_optional(connection)
    .await?;

    if deferred_job_id.is_none() {
        return Err(JobQueueError::LeaseLost {
            job_id: claimed_job.job_id,
            worker_id: claimed_job.locked_by.clone(),
            attempt: claimed_job.attempts,
        });
    }

    Ok(())
}
